import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const NOTIFICATION_TYPES = ['ALERT', 'MENTION'];

// schema.sql ck_notification_target_id_req: 이 유형은 targetId가 반드시 있어야 한다
const TARGET_ID_REQUIRED = ['DOCUMENT', 'POST', 'RESERVATION'];

// 가정: 바로가기 이동 경로는 targetType별 기본 경로 뒤에 targetId를 붙여 만든다
const SHORTCUT_BASE: Record<string, string> = {
  DOCUMENT: '/documents',
  POST: '/posts',
  RESERVATION: '/reservations',
};

// 가정: 대상이 없으면 알림 목록으로 이동한다
const DEFAULT_SHORTCUT = '/notifications';

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isIntegerValue(value: unknown): boolean {
  if (typeof value === 'number') {
    return Number.isSafeInteger(value);
  }
  if (typeof value === 'string') {
    return /^[0-9]{1,18}$/.test(value);
  }
  return false;
}

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || (typeof value === 'string' && value.trim() === '');
}

function requiredText(value: unknown, max: number, label: string): string {
  if (isBlank(value)) {
    throw invalid(label + '을(를) 입력해 주세요.');
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  const text = value.trim();
  if (text.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return text;
}

function optionalText(value: unknown, max: number, label: string): string | null {
  if (isBlank(value)) {
    return null;
  }
  return requiredText(value, max, label);
}

function shortcutOf(notificationId: number, targetType: string | null, targetId: number | null): string {
  if (targetType === null || targetId === null) {
    return DEFAULT_SHORTCUT;
  }
  const base = SHORTCUT_BASE[targetType] ?? '/' + encodeURIComponent(targetType);
  return base + '/' + targetId;
}

@Controller('api/v1')
export class FnSfr03604Controller {
  @Post('/notifications')
  @HttpCode(200)
  async createNotification(@Req() req: Request) {
    // 권한: 로그인 사용자 (특정 역할 제한 없음)
    currentUser(req);
    const data = checks.inputOf(req.body);

    if (isBlank(data['employeeId']) || !isIntegerValue(data['employeeId'])) {
      throw invalid('수신자를 선택해 주세요.');
    }
    const employeeId = String(data['employeeId']);

    const notificationType = requiredText(data['notificationType'], 20, '알림 구분');
    if (!NOTIFICATION_TYPES.includes(notificationType)) {
      throw invalid('알림 구분은 ALERT 또는 MENTION이어야 합니다.');
    }
    const eventType = requiredText(data['eventType'], 50, '연계 이벤트 유형');
    const title = requiredText(data['title'], 300, '제목');
    const summary = optionalText(data['summary'], 500, '요약');
    const targetType = optionalText(data['targetType'], 50, '바로가기 대상 유형');

    let targetId: string | null = null;
    if (!isBlank(data['targetId'])) {
      if (!isIntegerValue(data['targetId'])) {
        throw invalid('바로가기 대상 식별자는 숫자여야 합니다.');
      }
      targetId = String(data['targetId']);
    }
    if (targetType !== null && TARGET_ID_REQUIRED.includes(targetType) && targetId === null) {
      throw invalid('바로가기 대상 식별자를 입력해 주세요.');
    }

    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '수신 임직원이 조직도에 없습니다.');
      }

      // 값의 출처: read_yn 고정값 false(가정), occurred_at 현재 시각(가정)
      const rows = await db.query(
        'INSERT INTO notification '
          + '(employee_id, notification_type, event_type, title, summary, target_type, target_id, read_yn, occurred_at, created_at, updated_at) '
          + 'VALUES (CAST(:employeeId AS bigint), :notificationType, :eventType, :title, :summary, :targetType, CAST(:targetId AS bigint), false, now(), now(), now()) '
          + 'RETURNING notification_id AS "notificationId", target_type AS "targetType", target_id AS "targetId"',
        { employeeId, notificationType, eventType, title, summary, targetType, targetId },
      );
      const row = rows[0];
      const notificationId = Number(row['notificationId']);
      const savedTargetId = row['targetId'] === null || row['targetId'] === undefined ? null : Number(row['targetId']);
      const savedTargetType = row['targetType'] === null || row['targetType'] === undefined ? null : String(row['targetType']);
      return {
        notificationId,
        shortcutLink: shortcutOf(notificationId, savedTargetType, savedTargetId),
      };
    });
  }
}

