import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['ALERT', '알림'],
  ['MENTION', '@멘션'],
];

const TARGET_OPTIONS: [string, string][] = [
  ['POST', '게시물'],
  ['DOCUMENT', '문서'],
  ['RESERVATION', '예약'],
];

export default function FnSfr03604Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [notificationType, setNotificationType] = useState('ALERT');
  const [eventType, setEventType] = useState('');
  const [title, setTitle] = useState('');
  const [summary, setSummary] = useState('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [detail, setDetail] = useState<Row | undefined>(undefined);

  const alertCount = rows.filter((r) => r['notificationType'] === 'ALERT').length;
  const mentionCount = rows.filter((r) => r['notificationType'] === 'MENTION').length;

  function openForm() {
    setEmployeeId('');
    setNotificationType('ALERT');
    setEventType('');
    setTitle('');
    setSummary('');
    setTargetType('');
    setTargetId('');
    setOpen(true);
  }

  async function submit() {
    if (employeeId === '') {
      throw new Error('수신자를 선택해 주세요.');
    }
    if (eventType.trim() === '') {
      throw new Error('연계 이벤트 유형을 입력해 주세요.');
    }
    if (title.trim() === '') {
      throw new Error('제목을 입력해 주세요.');
    }
    if (targetType !== '' && targetId === '') {
      throw new Error('바로가기 대상 식별자를 입력해 주세요.');
    }
    const body: Row = {
      employeeId,
      notificationType,
      eventType: eventType.trim(),
      title: title.trim(),
    };
    if (summary.trim() !== '') {
      body['summary'] = summary.trim();
    }
    if (targetType !== '') {
      body['targetType'] = targetType;
    }
    if (targetId !== '') {
      body['targetId'] = targetId;
    }
    const result = await call<Row>('POST', '/notifications', role, body);
    const saved: Row = { ...body, ...result };
    setRows([saved, ...rows]);
    setOpen(false);
    notify('알림을 저장했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['전체 알림', rows.length],
            ['알림', alertCount],
            ['@멘션', mentionCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>저장한 알림</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openForm}>알림 등록</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 저장한 알림이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'notificationId', label: '알림 ID' },
            {
              key: 'employeeId',
              label: '수신자',
              render: (row) => <RefName table="employee" role={role} value={row['employeeId']} />,
            },
            {
              key: 'notificationType',
              label: '알림 구분',
              render: (row) => <Badge value={row['notificationType']} />,
            },
            { key: 'eventType', label: '연계 이벤트 유형' },
            { key: 'title', label: '제목' },
            { key: 'shortcutLink', label: '바로가기 링크' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="알림 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="수신자" required>
              <LookupSelect
                table="employee"
                role={role}
                value={employeeId}
                onChange={setEmployeeId}
                placeholder="수신자 선택"
              />
            </Field>
            <Field label="알림 구분" required>
              <Select value={notificationType} onChange={setNotificationType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="연계 이벤트 유형" required>
              <TextInput value={eventType} onChange={setEventType} />
            </Field>
            <Field label="제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="요약" wide>
              <TextInput value={summary} onChange={setSummary} multiline />
            </Field>
            <Field label="바로가기 대상 유형">
              <Select
                value={targetType}
                onChange={setTargetType}
                options={TARGET_OPTIONS}
                placeholder="대상 없음"
              />
            </Field>
            <Field label="바로가기 대상 식별자">
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="알림 상세" onClose={() => setDetail(undefined)}>
          <dl>
            <dt>알림 ID</dt>
            <dd>{String(detail['notificationId'] ?? '')}</dd>
            <dt>수신자</dt>
            <dd><RefName table="employee" role={role} value={detail['employeeId']} /></dd>
            <dt>알림 구분</dt>
            <dd><Badge value={detail['notificationType']} /></dd>
            <dt>연계 이벤트 유형</dt>
            <dd>{String(detail['eventType'] ?? '')}</dd>
            <dt>제목</dt>
            <dd>{String(detail['title'] ?? '')}</dd>
            <dt>요약</dt>
            <dd>{String(detail['summary'] ?? '')}</dd>
            <dt>바로가기 링크</dt>
            <dd>{String(detail['shortcutLink'] ?? '')}</dd>
          </dl>
        </Drawer>
      )}
    </div>
  );
}
